using DriveOS.Modules.Students.Domain.Suspensions;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Students.Infrastructure.Persistence.Configurations;
internal sealed class EnrollmentSuspensionConfiguration:IEntityTypeConfiguration<EnrollmentSuspension>{public void Configure(EntityTypeBuilder<EnrollmentSuspension>b){b.ToTable("enrollment_suspensions");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasConversion(x=>x.Value,x=>new EnrollmentSuspensionId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasColumnName("organization_id").HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.StudentId).HasColumnName("student_id").HasConversion(x=>x.Value,x=>new PersonId(x));b.Property(x=>x.EnrollmentId).HasColumnName("enrollment_id").HasConversion(x=>x.Value,x=>new DraftEnrollmentId(x));b.Property(x=>x.Reason).HasColumnName("reason").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Scope).HasColumnName("scope").HasConversion<int>();b.Property(x=>x.StartDate).HasColumnName("start_date");b.Property(x=>x.ExpectedEndDate).HasColumnName("expected_end_date");b.Property(x=>x.ImmediateActions).HasColumnName("immediate_actions").HasMaxLength(2000);b.Property(x=>x.BookingsDecision).HasColumnName("bookings_decision").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.FutureBookingsCount).HasColumnName("future_bookings_count");b.Property(x=>x.CreditDecision).HasColumnName("credit_decision").HasMaxLength(1000);b.Property(x=>x.NotificationPlan).HasColumnName("notification_plan").HasMaxLength(1000);b.Property(x=>x.ReviewDate).HasColumnName("review_date");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.NotificationStatus).HasColumnName("notification_status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.OperationalBlockId).HasColumnName("operational_block_id");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id").HasConversion(x=>x.Value,x=>new UserId(x));b.Property(x=>x.ActivatedAtUtc).HasColumnName("activated_at_utc");b.HasOne<DriveOS.Modules.Students.Domain.Students.Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);b.HasOne<DriveOS.Modules.Students.Domain.Enrollments.Enrollment>().WithMany().HasForeignKey(x=>x.EnrollmentId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.History).WithOne().HasForeignKey(x=>x.EnrollmentSuspensionId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.History).UsePropertyAccessMode(PropertyAccessMode.Field);b.HasIndex(x=>new{x.OrganizationId,x.StudentId,x.Status});b.HasIndex(x=>new{x.Status,x.StartDate});b.Ignore(x=>x.DomainEvents);}}
internal sealed class EnrollmentSuspensionHistoryConfiguration:IEntityTypeConfiguration<EnrollmentSuspensionHistory>{public void Configure(EntityTypeBuilder<EnrollmentSuspensionHistory>b){b.ToTable("enrollment_suspension_history");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.EnrollmentSuspensionId).HasColumnName("enrollment_suspension_id").HasConversion(x=>x.Value,x=>new EnrollmentSuspensionId(x));b.Property(x=>x.Action).HasColumnName("action").HasMaxLength(50);b.Property(x=>x.Detail).HasColumnName("detail").HasMaxLength(2000);b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id").HasConversion(x=>x.Value,x=>new UserId(x));b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.HasIndex(x=>new{x.EnrollmentSuspensionId,x.OccurredAtUtc});}}
